/**
 * useSSEProgress — 订阅 SSE 进度流的通用 hook
 *
 * 长任务进度推送的标准模式。消费方传 SSE 端点 URL,
 * hook 返回 { percent, stage, status, stages, error }。
 *
 * 后端 SSE 事件格式约定(各项目对齐):
 *   data: {"percent":62,"stage":"渲染中","status":"running","stages":[...]}
 *
 * 用法:
 *   const { percent, stage, status, stages } = useSSEProgress(
 *     taskId ? `/api/tasks/${taskId}/progress` : null
 *   );
 *   <OTaskProgress percent={percent} stage={stage} status={status} stages={stages} />
 */
'use client';

import { useEffect, useRef, useState } from 'react';
import type { TaskStatus, TaskStage } from './OTaskProgress';

export interface SSEProgressState {
  percent: number;
  stage?: string;
  status: TaskStatus;
  stages?: TaskStage[];
  etaSeconds?: number;
  error?: string;
}

export interface UseSSEProgressOptions {
  /** 额外 fetch headers(如 Authorization) */
  headers?: Record<string, string>;
  /** 自动重连次数,默认 3 */
  maxRetries?: number;
}

export function useSSEProgress(
  url: string | null,
  opts: UseSSEProgressOptions = {}
): SSEProgressState {
  const [state, setState] = useState<SSEProgressState>({ percent: 0, status: 'pending' });
  const retriesRef = useRef(0);
  const { maxRetries = 3 } = opts;

  useEffect(() => {
    if (!url) return;
    let cancelled = false;
    let es: EventSource | null = null;

    const connect = () => {
      // 注:EventSource 不支持自定义 header;若需 auth,后端用 query token 或 cookie
      es = new EventSource(url, { withCredentials: true });

      es.onmessage = (e) => {
        if (cancelled) return;
        try {
          const data = JSON.parse(e.data) as Partial<SSEProgressState>;
          setState(prev => ({ ...prev, ...data }));
          if (data.status === 'completed' || data.status === 'failed') {
            es?.close();
          }
        } catch {
          // 非 JSON 心跳,忽略
        }
      };

      es.onerror = () => {
        if (cancelled) return;
        es?.close();
        if (retriesRef.current < maxRetries) {
          retriesRef.current += 1;
          setTimeout(connect, 1000 * retriesRef.current);
        } else {
          setState(prev => ({ ...prev, status: 'failed', error: 'SSE 连接中断' }));
        }
      };
    };

    connect();
    return () => { cancelled = true; es?.close(); };
  }, [url, maxRetries]);

  return state;
}
